//! The desktop crate's build script: tauri-build reads `tauri.conf.json`, embeds the
//! Windows icon and resolves the capabilities and the app's command manifest at build time.

use std::error::Error;

use tauri_build::{AppManifest, Attributes};

/// The app's own commands. tauri-build generates an `allow-<command>` and a
/// `deny-<command>` permission for each, in `permissions/autogenerated/` (committed and
/// pinned by `scripts/tauri-hardening.mjs`), and the UI can call one only when a
/// capability grants its `allow-<command>`. `permissions/default.toml` keeps the ACL on
/// for app commands even if this list were empty (ADR-0017).
const COMMANDS: &[&str] = &[
    "server_profile",
    "set_server_profile",
    "check_server",
    "login",
    "login_mfa",
    "logout",
    "register",
    "step_up",
    "mfa_enroll",
    "mfa_confirm",
    "mfa_reset",
    "me",
    "change_password",
    "sessions",
    "revoke_session",
    "users",
    "patch_user",
    "invites",
    "create_invite",
    "revoke_invite",
    "start_link",
    "link_status",
    "create_offline_account",
    "accounts",
    "accounts_awaiting_approval",
    "account",
    "delete_account",
    "approve_account",
    "refuse_account",
    "relink_account",
    "account_grants",
    "create_grant",
    "change_grant",
    "revoke_grant",
    "open_verification_link",
    "watch_events",
    "bots",
    "bot",
    "modes",
    "create_mode",
    "create_mode_with_commands",
    "update_mode",
    "update_mode_with_commands",
    "delete_mode",
    "patch_bot",
    "set_bot_mode",
    "start_bot",
    "stop_bot",
    "restart_bot",
    "reset_bot",
    "resume_bot",
    "bot_chat",
    "send_chat",
    "send_command",
    "server_settings",
    "create_server_settings",
    "update_server_settings",
    "delete_server_settings",
    "preview_chat_formats",
];

fn main() -> Result<(), Box<dyn Error>> {
    tauri_build::try_build(Attributes::new().app_manifest(AppManifest::new().commands(COMMANDS)))?;
    Ok(())
}
